-- Content-only, atomic update for backend-engineering; preserves previous assignment criteria.
BEGIN;
CREATE TEMP TABLE legacy_guides(payload jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO legacy_guides(payload) VALUES ($legacy_payload$[{"slug":"backend-engineering","task_number":1,"title":"REST API Design","old_description":"[[AZ]]\nTələbə layihələri üçün resurs yönümlü REST API dizayn et və müqaviləsini nümunələrlə sənədləşdir.\n\n[[EN]]\nDesign a resource-oriented REST API for student projects and document its contract with examples.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nLayihələri yaratmaq, siyahılamaq, açmaq və yeniləmək üçün REST API planı hazırlayacaqsan. Bu tapşırıqda əsas nəticə işlək server yox, aydın API müqaviləsidir.\n\n## 2. Başlamazdan əvvəl\nAPI, HTTP sorğusu, GET/POST/PUT/PATCH, JSON və 404/422 kimi status kodlarının əsasları. VS Code, terminal və GitHub-dan başlanğıc səviyyədə istifadə.\n\n## 3. Addım-addım icra\n1. GitHub-da özünə boş `student-project-api` repo-su yarat və VS Code-da aç. Sıfırdan başla.\n2. `README.md` və `openapi.yaml` faylları yarat.\n3. Dörd əməliyyat müəyyən et: layihələri siyahıla, bir layihəyə bax, layihə yarat və mövcud layihəni yenilə.\n4. Hər əməliyyat üçün HTTP metodu, URL, sorğu nümunəsi və cavab nümunəsi yaz.\n5. Layihə tapılmadıqda 404, məlumat yanlışdırsa 422 qaytarılmasını təsvir et.\n6. Ən azı 5 sorğu nümunəsi və gözlənilən status kodunu əlavə et.\n7. README-də API-ni izah et, YAML sintaksisini yoxla, sonra commit edib GitHub-a push et.\n\n## 4. Konkret nümunə və izah\n`GET /projects` siyahını, `GET /projects/{id}` bir layihəni qaytarsın; `POST /projects` yaratsın, `PATCH /projects/{id}` yeniləsin. Hər əməliyyat üçün JSON nümunəsi və məcburi sahələr yaz. Bu mərhələdə serveri işə salmaq tələb olunmur.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, `openapi.yaml`, ən azı 5 sorğu/cavab nümunəsi və API qərarlarını izah edən README.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nDörd əməliyyat və ən azı 5 sorğu/cavab nümunəsi var. 404 olmayan layihəni, 422 isə səhv sahələri izah edir; OpenAPI faylı sintaksis yoxlamasından keçir.\n\n[[EN]]\n## 1. Goal\nPlan a REST API for listing, viewing, creating, and updating projects. The main deliverable is a clear API contract, not a running server.\n\n## 2. Before you start\nBasic API and HTTP concepts, GET/POST/PUT/PATCH, JSON, and status codes such as 404 and 422. Basic VS Code, terminal, and GitHub use.\n\n## 3. Step-by-step work\n1. Create your own empty GitHub repository named `student-project-api` and open it in VS Code. Start from scratch.\n2. Create `README.md` and `openapi.yaml`.\n3. Define four operations: list projects, view one project, create a project, and update a project.\n4. For each operation, write the HTTP method, URL, example request, and example response.\n5. Describe a 404 response when a project is missing and a 422 response for invalid input.\n6. Add at least five request examples and their expected status codes.\n7. Explain the API in README, validate the YAML syntax, then commit and push to GitHub.\n\n## 4. Concrete example and explanation\nUse `GET /projects`, `GET /projects/{id}`, `POST /projects`, and `PATCH /projects/{id}`. Include JSON examples and required fields for every operation. Running a server is not required yet.\n\n## 5. What to submit\nYour own GitHub repository link, `openapi.yaml`, at least five request/response examples, and a README explaining the API decisions.\n\n## 6. How to check your work\nInclude four operations and at least five request/response examples. Use 404 for missing resources and 422 for invalid fields; validate OpenAPI syntax.","new_description":"[[AZ]]\nTələbə layihələri üçün resurs yönümlü REST API dizayn et və müqaviləsini nümunələrlə sənədləşdir.\n\nPulsuz alətlər: Visual Studio Code, Python (free), FastAPI (open source), GitHub Free. Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nDesign a resource-oriented REST API for student projects and document its contract with examples.\n\nFree tools: Visual Studio Code, Python (free), FastAPI (open source), GitHub Free. Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** `GET /projects` siyahı, `GET /projects/1` detal, `POST /projects` yaradılma üçün request/response JSON yaz; hələ server lazım deyil.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Python layihəsində lokal HTTP endpoint və Pydantic input modeli yarat; ödənişli server lazım deyil.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / backend-engineering / task-1` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. README-də `Project(id,title,status)` modelini və 4 route-u göstər. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. Hər route üçün uğurlu cavab və 404/422 kimi xəta nümunəsi yaz. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. `openapi.yaml`-ı struktura görə yoxla, 5 request/response cütünü əlavə et. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: `GET /projects` siyahı, `GET /projects/1` detal, `POST /projects` yaradılma üçün request/response JSON yaz; hələ server lazım deyil. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\n`GET /projects` siyahı, `GET /projects/1` detal, `POST /projects` yaradılma üçün request/response JSON yaz; hələ server lazım deyil.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nLayihələri yaratmaq, siyahılamaq, açmaq və yeniləmək üçün REST API planı hazırlayacaqsan. Bu tapşırıqda əsas nəticə işlək server yox, aydın API müqaviləsidir.\n\n## 2. Başlamazdan əvvəl\nAPI, HTTP sorğusu, GET/POST/PUT/PATCH, JSON və 404/422 kimi status kodlarının əsasları. VS Code, terminal və GitHub-dan başlanğıc səviyyədə istifadə.\n\n## 3. Addım-addım icra\n1. GitHub-da özünə boş `student-project-api` repo-su yarat və VS Code-da aç. Sıfırdan başla.\n2. `README.md` və `openapi.yaml` faylları yarat.\n3. Dörd əməliyyat müəyyən et: layihələri siyahıla, bir layihəyə bax, layihə yarat və mövcud layihəni yenilə.\n4. Hər əməliyyat üçün HTTP metodu, URL, sorğu nümunəsi və cavab nümunəsi yaz.\n5. Layihə tapılmadıqda 404, məlumat yanlışdırsa 422 qaytarılmasını təsvir et.\n6. Ən azı 5 sorğu nümunəsi və gözlənilən status kodunu əlavə et.\n7. README-də API-ni izah et, YAML sintaksisini yoxla, sonra commit edib GitHub-a push et.\n\n## 4. Konkret nümunə və izah\n`GET /projects` siyahını, `GET /projects/{id}` bir layihəni qaytarsın; `POST /projects` yaratsın, `PATCH /projects/{id}` yeniləsin. Hər əməliyyat üçün JSON nümunəsi və məcburi sahələr yaz. Bu mərhələdə serveri işə salmaq tələb olunmur.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, `openapi.yaml`, ən azı 5 sorğu/cavab nümunəsi və API qərarlarını izah edən README.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nDörd əməliyyat və ən azı 5 sorğu/cavab nümunəsi var. 404 olmayan layihəni, 422 isə səhv sahələri izah edir; OpenAPI faylı sintaksis yoxlamasından keçir.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Document GET /projects, GET /projects/1 and POST /projects request/response examples before coding.\n\n## Free tools and platforms — getting started\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Create local Python HTTP endpoints with Pydantic validation; paid hosting is unnecessary.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / backend-engineering / task-1` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Define a Project(id,title,status) model and four routes in README. Demonstrate it with source code, a test, file or diagram.\n4. Write success and error examples including 404 and 422. Demonstrate it with source code, a test, file or diagram.\n5. Validate the OpenAPI file and include five request/response pairs. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Document GET /projects, GET /projects/1 and POST /projects request/response examples before coding. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nDocument GET /projects, GET /projects/1 and POST /projects request/response examples before coding.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nPlan a REST API for listing, viewing, creating, and updating projects. The main deliverable is a clear API contract, not a running server.\n\n## 2. Before you start\nBasic API and HTTP concepts, GET/POST/PUT/PATCH, JSON, and status codes such as 404 and 422. Basic VS Code, terminal, and GitHub use.\n\n## 3. Step-by-step work\n1. Create your own empty GitHub repository named `student-project-api` and open it in VS Code. Start from scratch.\n2. Create `README.md` and `openapi.yaml`.\n3. Define four operations: list projects, view one project, create a project, and update a project.\n4. For each operation, write the HTTP method, URL, example request, and example response.\n5. Describe a 404 response when a project is missing and a 422 response for invalid input.\n6. Add at least five request examples and their expected status codes.\n7. Explain the API in README, validate the YAML syntax, then commit and push to GitHub.\n\n## 4. Concrete example and explanation\nUse `GET /projects`, `GET /projects/{id}`, `POST /projects`, and `PATCH /projects/{id}`. Include JSON examples and required fields for every operation. Running a server is not required yet.\n\n## 5. What to submit\nYour own GitHub repository link, `openapi.yaml`, at least five request/response examples, and a README explaining the API decisions.\n\n## 6. How to check your work\nInclude four operations and at least five request/response examples. Use 404 for missing resources and 422 for invalid fields; validate OpenAPI syntax."},{"slug":"backend-engineering","task_number":2,"title":"PostgreSQL Data Model","old_description":"[[AZ]]\nLayihə, üzv və tapşırıq məlumatları üçün normallaşdırılmış PostgreSQL modeli qur.\n\n[[EN]]\nCreate a normalized PostgreSQL model for projects, members, and tasks.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nLayihə, üzv və tapşırıq cədvəllərini əlaqələndirən PostgreSQL məlumat modeli quracaqsan.\n\n## 2. Başlamazdan əvvəl\nTapşırıq 1-dəki öz backend repo-n, SQL cədvəl/primary key/foreign key anlayışları və PostgreSQL-in əsasları. Yalnız lokal və ya test bazası istifadə et.\n\n## 3. Addım-addım icra\n1. Öz backend repo-nu davam etdir.\n2. Projects, users və tasks cədvəllərinin sütunlarını və UUID primary key-lərini müəyyən et.\n3. Project membership üçün ayrıca əlaqə cədvəli yarat; foreign key və unique constraint-lər əlavə et.\n4. Task sahibi, yaradılma vaxtı və status sahələrini müəyyən et.\n5. Ən azı 10 sintetik qeyd daxil et və valid/invalid əlaqələri yoxla.\n6. Schema diagramı və migration addımlarını README-də sənədləşdir.\n\n## 4. Konkret nümunə və izah\nƏsas açar (primary key) qeydin unikal ID-sidir; xarici açar (foreign key) başqa cədvələ istinaddır. `project_members(project_id,user_id)` cütlüyü unikal olsun ki, eyni üzv eyni layihəyə iki dəfə əlavə edilməsin.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, schema/migration SQL, ER diaqramı, sintetik seed data və constraint-ləri yoxlayan test sorğuları. Yanlış foreign key və təkrar üzvlük rədd edilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nSQL boş test bazasında icra olunur. Mövcud olmayan user/project ID-si və təkrar üzvlük rədd edilir; diaqram SQL-dəki əlaqələrlə uyğun gəlir.\n\n[[EN]]\n## 1. Goal\nDesign a PostgreSQL data model connecting projects, members, and tasks.\n\n## 2. Before you start\nYour own backend repository from Task 1, SQL tables/primary keys/foreign keys, and PostgreSQL basics. Use only a local or test database.\n\n## 3. Step-by-step work\n1. Continue your own backend repository.\n2. Define columns and UUID primary keys for projects, users, and tasks.\n3. Create a separate project-membership table with foreign keys and unique constraints.\n4. Define task owner, creation time, and status fields.\n5. Insert at least ten synthetic records and test valid/invalid relationships.\n6. Document the schema diagram and migration steps in the README.\n\n## 4. Concrete example and explanation\nA primary key uniquely identifies a row; a foreign key references another table. Make `(project_id,user_id)` unique in `project_members` to prevent duplicate memberships.\n\n## 5. What to submit\nYour own GitHub repository link, schema/migration SQL, ER diagram, synthetic seed data, and test queries for constraints. Invalid foreign keys and duplicate memberships must be rejected.\n\n## 6. How to check your work\nRun SQL on an empty test database. Reject nonexistent user/project IDs and duplicate memberships; keep the diagram consistent with SQL.","new_description":"[[AZ]]\nLayihə, üzv və tapşırıq məlumatları üçün normallaşdırılmış PostgreSQL modeli qur.\n\nPulsuz alətlər: PostgreSQL (local, free), diagrams.net, Visual Studio Code. Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nCreate a normalized PostgreSQL model for projects, members, and tasks.\n\nFree tools: PostgreSQL (local, free), diagrams.net, Visual Studio Code. Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** `projects`, `members`, `tasks` cədvəlləri üçün PK/FK və NOT NULL istifadə et; üzv olmayan layihəyə task yazma.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **PostgreSQL (local, free)** — https://www.postgresql.org. Lokal test DB-də cədvəllər qur; production Supabase/Talora bazasında SQL çalışdırma.\n- **diagrams.net** — https://app.diagrams.net. Blank diagram seç, addımları oxlarla birləşdir və PNG/PDF çıxart.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / backend-engineering / task-2` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. ERD-də hər cədvəlin sahələrini və əlaqəni göstər. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. Lokal PostgreSQL-də `CREATE TABLE` və FK/UNIQUE/CHECK qaydalarını yaz. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. Keçərli və keçərsiz 5 INSERT-i test et; real Talora bazasına qoşulma. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: `projects`, `members`, `tasks` cədvəlləri üçün PK/FK və NOT NULL istifadə et; üzv olmayan layihəyə task yazma. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\n`projects`, `members`, `tasks` cədvəlləri üçün PK/FK və NOT NULL istifadə et; üzv olmayan layihəyə task yazma.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nLayihə, üzv və tapşırıq cədvəllərini əlaqələndirən PostgreSQL məlumat modeli quracaqsan.\n\n## 2. Başlamazdan əvvəl\nTapşırıq 1-dəki öz backend repo-n, SQL cədvəl/primary key/foreign key anlayışları və PostgreSQL-in əsasları. Yalnız lokal və ya test bazası istifadə et.\n\n## 3. Addım-addım icra\n1. Öz backend repo-nu davam etdir.\n2. Projects, users və tasks cədvəllərinin sütunlarını və UUID primary key-lərini müəyyən et.\n3. Project membership üçün ayrıca əlaqə cədvəli yarat; foreign key və unique constraint-lər əlavə et.\n4. Task sahibi, yaradılma vaxtı və status sahələrini müəyyən et.\n5. Ən azı 10 sintetik qeyd daxil et və valid/invalid əlaqələri yoxla.\n6. Schema diagramı və migration addımlarını README-də sənədləşdir.\n\n## 4. Konkret nümunə və izah\nƏsas açar (primary key) qeydin unikal ID-sidir; xarici açar (foreign key) başqa cədvələ istinaddır. `project_members(project_id,user_id)` cütlüyü unikal olsun ki, eyni üzv eyni layihəyə iki dəfə əlavə edilməsin.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, schema/migration SQL, ER diaqramı, sintetik seed data və constraint-ləri yoxlayan test sorğuları. Yanlış foreign key və təkrar üzvlük rədd edilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nSQL boş test bazasında icra olunur. Mövcud olmayan user/project ID-si və təkrar üzvlük rədd edilir; diaqram SQL-dəki əlaqələrlə uyğun gəlir.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Design project/member/task tables with primary/foreign keys and invalid-reference tests.\n\n## Free tools and platforms — getting started\n- **PostgreSQL (local, free)** — https://www.postgresql.org. Use a local test database; never run these exercises against production Talora/Supabase.\n- **diagrams.net** — https://app.diagrams.net. Create a blank diagram, connect steps with arrows and export PNG/PDF.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / backend-engineering / task-2` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Draw an ERD showing fields and relationships. Demonstrate it with source code, a test, file or diagram.\n4. Create the local PostgreSQL schema with keys and constraints. Demonstrate it with source code, a test, file or diagram.\n5. Test five valid/invalid inserts; never run this against Talora production. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Design project/member/task tables with primary/foreign keys and invalid-reference tests. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nDesign project/member/task tables with primary/foreign keys and invalid-reference tests.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nDesign a PostgreSQL data model connecting projects, members, and tasks.\n\n## 2. Before you start\nYour own backend repository from Task 1, SQL tables/primary keys/foreign keys, and PostgreSQL basics. Use only a local or test database.\n\n## 3. Step-by-step work\n1. Continue your own backend repository.\n2. Define columns and UUID primary keys for projects, users, and tasks.\n3. Create a separate project-membership table with foreign keys and unique constraints.\n4. Define task owner, creation time, and status fields.\n5. Insert at least ten synthetic records and test valid/invalid relationships.\n6. Document the schema diagram and migration steps in the README.\n\n## 4. Concrete example and explanation\nA primary key uniquely identifies a row; a foreign key references another table. Make `(project_id,user_id)` unique in `project_members` to prevent duplicate memberships.\n\n## 5. What to submit\nYour own GitHub repository link, schema/migration SQL, ER diagram, synthetic seed data, and test queries for constraints. Invalid foreign keys and duplicate memberships must be rejected.\n\n## 6. How to check your work\nRun SQL on an empty test database. Reject nonexistent user/project IDs and duplicate memberships; keep the diagram consistent with SQL."},{"slug":"backend-engineering","task_number":3,"title":"Authentication and Validation","old_description":"[[AZ]]\nGiriş və qeydiyyat endpoint-lərini input validasiyası və təhlükəsiz xəta cavabları ilə qur.\n\n[[EN]]\nBuild sign-up and sign-in endpoints with input validation and safe error responses.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nQeydiyyat və giriş axınında məlumatı yoxlayacaq, parolu təhlükəsiz saxlayacaq və artıq hesab məlumatını açıqlamayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz backend repo-n, HTTP request/response, validation və parol hash anlayışı. Lokal test bazası və ya mock auth istifadə et; real istifadəçi məlumatı işlətmə.\n\n## 3. Addım-addım icra\n1. Öz repo-nu davam etdir.\n2. Qeydiyyat və giriş endpoint-ləri üçün request/response formatlarını müəyyən et.\n3. Email formatı, parol minimumları və məcburi sahələr üçün validation yaz.\n4. Parolu plaintext saxlamadan uyğun password-hashing kitabxanasından istifadə et; öz hash alqoritmini yazma.\n5. Yanlış parol və mövcud olmayan hesab üçün eyni ümumi error mesajı qaytar.\n6. Uğurlu giriş, invalid input, yanlış credential və təkrar email halları üçün testlər yaz.\n\n## 4. Konkret nümunə və izah\nAPI planın hələ işlək server deyilsə, bildiyin dilin bir framework-ü ilə lokal server qur və başlatma əmrini README-yə yaz. Sonra `POST /auth/register` və `POST /auth/login` əlavə et. Parol hash-i geri açılan şifrələmə deyil; parolu yoxlamaq üçün kitabxananın verify funksiyası işlədilir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, auth endpoint-ləri, validation/hash tətbiqi, testlər və təhlükəsizlik qərarlarını izah edən README. Log və cavablarda parol/token görünməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nQeydiyyat işləyir; saxlanan dəyər parolun özü deyil. Düzgün giriş uğurludur; səhv parol və olmayan hesab eyni ümumi xəta verir. Cavab və logda parol/hash/token yoxdur.\n\n[[EN]]\n## 1. Goal\nValidate registration and login, store passwords safely, and avoid revealing unnecessary account information.\n\n## 2. Before you start\nYour own backend repository, HTTP requests/responses, validation, and password hashing. Use a local test database or mock auth and never use real user data.\n\n## 3. Step-by-step work\n1. Continue your own repository.\n2. Define request/response formats for registration and login endpoints.\n3. Validate email format, password requirements, and required fields.\n4. Use a reputable password-hashing library; never store plaintext passwords or invent your own hashing algorithm.\n5. Return the same general error for a wrong password and a nonexistent account.\n6. Test successful login, invalid input, incorrect credentials, and duplicate email.\n\n## 4. Concrete example and explanation\nIf you only have an API contract, create a local server using a framework in a language you know and document the start command. Add `POST /auth/register` and `POST /auth/login`. A password hash is not reversible encryption; use the library verification function.\n\n## 5. What to submit\nYour own GitHub repository link, auth endpoints, validation/hashing implementation, tests, and a README explaining security decisions. Passwords and tokens must never appear in logs or responses.\n\n## 6. How to check your work\nRegistration works and stores no plaintext password. Valid login succeeds; wrong passwords and unknown accounts return the same general error. Never expose passwords, hashes, or tokens in responses/logs.","new_description":"[[AZ]]\nGiriş və qeydiyyat endpoint-lərini input validasiyası və təhlükəsiz xəta cavabları ilə qur.\n\nPulsuz alətlər: Python (free), FastAPI (open source), Visual Studio Code. Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nBuild sign-up and sign-in endpoints with input validation and safe error responses.\n\nFree tools: Python (free), FastAPI (open source), Visual Studio Code. Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** Məsələn, qeydiyyatda boş email 422, eyni email duplicate, yanlış login isə neytral xəta verməlidir.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Python layihəsində lokal HTTP endpoint və Pydantic input modeli yarat; ödənişli server lazım deyil.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / backend-engineering / task-3` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. Pydantic ilə input validation və parol hash komponentini seç. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. Şifrəni plaintext/log-da saxlamadan lokal sintetik hesab yarat. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. Yanlış email, boş şifrə və səhv credential halları üçün test əlavə et. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: Məsələn, qeydiyyatda boş email 422, eyni email duplicate, yanlış login isə neytral xəta verməlidir. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\nMəsələn, qeydiyyatda boş email 422, eyni email duplicate, yanlış login isə neytral xəta verməlidir.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nQeydiyyat və giriş axınında məlumatı yoxlayacaq, parolu təhlükəsiz saxlayacaq və artıq hesab məlumatını açıqlamayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz backend repo-n, HTTP request/response, validation və parol hash anlayışı. Lokal test bazası və ya mock auth istifadə et; real istifadəçi məlumatı işlətmə.\n\n## 3. Addım-addım icra\n1. Öz repo-nu davam etdir.\n2. Qeydiyyat və giriş endpoint-ləri üçün request/response formatlarını müəyyən et.\n3. Email formatı, parol minimumları və məcburi sahələr üçün validation yaz.\n4. Parolu plaintext saxlamadan uyğun password-hashing kitabxanasından istifadə et; öz hash alqoritmini yazma.\n5. Yanlış parol və mövcud olmayan hesab üçün eyni ümumi error mesajı qaytar.\n6. Uğurlu giriş, invalid input, yanlış credential və təkrar email halları üçün testlər yaz.\n\n## 4. Konkret nümunə və izah\nAPI planın hələ işlək server deyilsə, bildiyin dilin bir framework-ü ilə lokal server qur və başlatma əmrini README-yə yaz. Sonra `POST /auth/register` və `POST /auth/login` əlavə et. Parol hash-i geri açılan şifrələmə deyil; parolu yoxlamaq üçün kitabxananın verify funksiyası işlədilir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, auth endpoint-ləri, validation/hash tətbiqi, testlər və təhlükəsizlik qərarlarını izah edən README. Log və cavablarda parol/token görünməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nQeydiyyat işləyir; saxlanan dəyər parolun özü deyil. Düzgün giriş uğurludur; səhv parol və olmayan hesab eyni ümumi xəta verir. Cavab və logda parol/hash/token yoxdur.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Test empty email, duplicate signup and neutral error responses for failed logins.\n\n## Free tools and platforms — getting started\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Create local Python HTTP endpoints with Pydantic validation; paid hosting is unnecessary.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / backend-engineering / task-3` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Validate input using Pydantic and choose a maintained password hashing utility. Demonstrate it with source code, a test, file or diagram.\n4. Create local fictional accounts without storing or logging plaintext passwords. Demonstrate it with source code, a test, file or diagram.\n5. Test invalid email, missing password and failed sign-in with neutral errors. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Test empty email, duplicate signup and neutral error responses for failed logins. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nTest empty email, duplicate signup and neutral error responses for failed logins.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nValidate registration and login, store passwords safely, and avoid revealing unnecessary account information.\n\n## 2. Before you start\nYour own backend repository, HTTP requests/responses, validation, and password hashing. Use a local test database or mock auth and never use real user data.\n\n## 3. Step-by-step work\n1. Continue your own repository.\n2. Define request/response formats for registration and login endpoints.\n3. Validate email format, password requirements, and required fields.\n4. Use a reputable password-hashing library; never store plaintext passwords or invent your own hashing algorithm.\n5. Return the same general error for a wrong password and a nonexistent account.\n6. Test successful login, invalid input, incorrect credentials, and duplicate email.\n\n## 4. Concrete example and explanation\nIf you only have an API contract, create a local server using a framework in a language you know and document the start command. Add `POST /auth/register` and `POST /auth/login`. A password hash is not reversible encryption; use the library verification function.\n\n## 5. What to submit\nYour own GitHub repository link, auth endpoints, validation/hashing implementation, tests, and a README explaining security decisions. Passwords and tokens must never appear in logs or responses.\n\n## 6. How to check your work\nRegistration works and stores no plaintext password. Valid login succeeds; wrong passwords and unknown accounts return the same general error. Never expose passwords, hashes, or tokens in responses/logs."},{"slug":"backend-engineering","task_number":4,"title":"Integrated Backend Service","old_description":"[[AZ]]\nTələblər, API və təhlükəsizlik testləri ilə tamamlanmış backend service nümunəsi təqdim et.\n\n[[EN]]\nDeliver a backend service feature supported by requirements, API, and security tests.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nTask yaratmaq, siyahılamaq və statusunu dəyişmək üçün tam backend servisi hazırlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz backend repo-n, REST API, SQL migration, validation, authentication və testlərin əsasları. Yalnız sintetik istifadəçi və məlumatlardan istifadə et.\n\n## 3. Addım-addım icra\n1. Öz əvvəlki backend layihəni davam etdir.\n2. Task create/list/detail/status-update endpoint-lərini qur.\n3. Hər endpoint üçün input schema, status code və error formatı müəyyən et.\n4. Hər istifadəçinin yalnız özünə icazə verilən task-lara baxmasını server tərəfdə yoxla.\n5. Migration və seed data əlavə et; production bazasına qoşulma.\n6. Uğurlu axın, invalid input, missing ID və ownership pozuntusu üçün test yaz.\n\n## 4. Konkret nümunə və izah\n`POST /tasks`, `GET /tasks`, `GET /tasks/{id}` və `PATCH /tasks/{id}/status` əməliyyatlarını əvvəlki schema və auth ilə birləşdir. İki sintetik istifadəçi yarat: A istifadəçisi B-nin tapşırığını oxuya və dəyişə bilməsin. Bu inteqrasiya mərhələsidir; yekun deployment 10-cu tapşırıqdır.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işlək API, migration/seed, endpoint nümunələri və test nəticələri. Başqa istifadəçinin task-ına icazəsiz baxış və dəyişiklik mümkün olmamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nNormal CRUD axını ilə yanaşı boş başlıq, olmayan ID və başqa istifadəçinin tapşırığı yoxlanılıb. Layihə yalnız ayrıca test bazasına qoşulur.\n\n[[EN]]\n## 1. Goal\nBuild a backend service to create tasks, list them, and update their status.\n\n## 2. Before you start\nYour own backend repository, REST APIs, SQL migrations, validation, authentication, and basic testing. Use synthetic users and data only.\n\n## 3. Step-by-step work\n1. Continue your own backend project.\n2. Implement task create/list/detail/status-update endpoints.\n3. Define input schemas, status codes, and error formats for each endpoint.\n4. Enforce on the server that users can access only tasks they are authorized to see.\n5. Add migrations and seed data; do not connect to a production database.\n6. Test success, invalid input, missing IDs, and ownership violations.\n\n## 4. Concrete example and explanation\nIntegrate `POST /tasks`, `GET /tasks`, `GET /tasks/{id}`, and `PATCH /tasks/{id}/status` with your schema and auth. Synthetic user A must not read or modify user B’s task. Deployment comes in Task 10.\n\n## 5. What to submit\nYour own GitHub repository link, working API, migrations/seed data, endpoint examples, and test results. Unauthorized access to or modification of another user's task must be prevented.\n\n## 6. How to check your work\nTest normal operations, empty titles, missing IDs, and cross-user access. Use a separate test database.","new_description":"[[AZ]]\nTələblər, API və təhlükəsizlik testləri ilə tamamlanmış backend service nümunəsi təqdim et.\n\nPulsuz alətlər: Python (free), FastAPI (open source), PostgreSQL (local, free), pytest (open source). Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nDeliver a backend service feature supported by requirements, API, and security tests.\n\nFree tools: Python (free), FastAPI (open source), PostgreSQL (local, free), pytest (open source). Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** `POST /tasks`, `GET /tasks`, `PATCH /tasks/1` route-ları owner authorization ilə işləsin.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Python layihəsində lokal HTTP endpoint və Pydantic input modeli yarat; ödənişli server lazım deyil.\n- **PostgreSQL (local, free)** — https://www.postgresql.org. Lokal test DB-də cədvəllər qur; production Supabase/Talora bazasında SQL çalışdırma.\n- **pytest (open source)** — https://docs.pytest.org. Lokal Python unit/integration testləri yaz, nəticələri `pytest` ilə təsdiqlə.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / backend-engineering / task-4` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. Əvvəlki schema, validation və authorization qaydalarını bir servisə birləşdir. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. İcazəsiz istifadəçinin başqa task-a daxil olmasını 403/404 ilə blokla. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. Lokal DB və sintetik istifadəçilərlə 6 integration test yaz. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: `POST /tasks`, `GET /tasks`, `PATCH /tasks/1` route-ları owner authorization ilə işləsin. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\n`POST /tasks`, `GET /tasks`, `PATCH /tasks/1` route-ları owner authorization ilə işləsin.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nTask yaratmaq, siyahılamaq və statusunu dəyişmək üçün tam backend servisi hazırlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz backend repo-n, REST API, SQL migration, validation, authentication və testlərin əsasları. Yalnız sintetik istifadəçi və məlumatlardan istifadə et.\n\n## 3. Addım-addım icra\n1. Öz əvvəlki backend layihəni davam etdir.\n2. Task create/list/detail/status-update endpoint-lərini qur.\n3. Hər endpoint üçün input schema, status code və error formatı müəyyən et.\n4. Hər istifadəçinin yalnız özünə icazə verilən task-lara baxmasını server tərəfdə yoxla.\n5. Migration və seed data əlavə et; production bazasına qoşulma.\n6. Uğurlu axın, invalid input, missing ID və ownership pozuntusu üçün test yaz.\n\n## 4. Konkret nümunə və izah\n`POST /tasks`, `GET /tasks`, `GET /tasks/{id}` və `PATCH /tasks/{id}/status` əməliyyatlarını əvvəlki schema və auth ilə birləşdir. İki sintetik istifadəçi yarat: A istifadəçisi B-nin tapşırığını oxuya və dəyişə bilməsin. Bu inteqrasiya mərhələsidir; yekun deployment 10-cu tapşırıqdır.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işlək API, migration/seed, endpoint nümunələri və test nəticələri. Başqa istifadəçinin task-ına icazəsiz baxış və dəyişiklik mümkün olmamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nNormal CRUD axını ilə yanaşı boş başlıq, olmayan ID və başqa istifadəçinin tapşırığı yoxlanılıb. Layihə yalnız ayrıca test bazasına qoşulur.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Build task create/list/update endpoints with ownership checks.\n\n## Free tools and platforms — getting started\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Create local Python HTTP endpoints with Pydantic validation; paid hosting is unnecessary.\n- **PostgreSQL (local, free)** — https://www.postgresql.org. Use a local test database; never run these exercises against production Talora/Supabase.\n- **pytest (open source)** — https://docs.pytest.org. Write local Python tests and run them with pytest.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / backend-engineering / task-4` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Connect prior schema, input validation and authorization in one service. Demonstrate it with source code, a test, file or diagram.\n4. Deny cross-user task access with safe 403/404 behavior. Demonstrate it with source code, a test, file or diagram.\n5. Run six integration tests with a local database and fictional users. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Build task create/list/update endpoints with ownership checks. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nBuild task create/list/update endpoints with ownership checks.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nBuild a backend service to create tasks, list them, and update their status.\n\n## 2. Before you start\nYour own backend repository, REST APIs, SQL migrations, validation, authentication, and basic testing. Use synthetic users and data only.\n\n## 3. Step-by-step work\n1. Continue your own backend project.\n2. Implement task create/list/detail/status-update endpoints.\n3. Define input schemas, status codes, and error formats for each endpoint.\n4. Enforce on the server that users can access only tasks they are authorized to see.\n5. Add migrations and seed data; do not connect to a production database.\n6. Test success, invalid input, missing IDs, and ownership violations.\n\n## 4. Concrete example and explanation\nIntegrate `POST /tasks`, `GET /tasks`, `GET /tasks/{id}`, and `PATCH /tasks/{id}/status` with your schema and auth. Synthetic user A must not read or modify user B’s task. Deployment comes in Task 10.\n\n## 5. What to submit\nYour own GitHub repository link, working API, migrations/seed data, endpoint examples, and test results. Unauthorized access to or modification of another user's task must be prevented.\n\n## 6. How to check your work\nTest normal operations, empty titles, missing IDs, and cross-user access. Use a separate test database."},{"slug":"backend-engineering","task_number":5,"title":"Pagination and Filtering","old_description":"[[AZ]]\nBöyük layihə siyahısını sabit pagination və yoxlanıla bilən filter-lərlə təqdim et.\n\n[[EN]]\nServe a large project list with stable pagination and validated filters.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nLayihə endpoint-inə axtarış, status filter-i və sabit səhifələmə əlavə edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz backend repo-n, SQL query-lər, API query parametrləri və testlər. Ən azı 100 sintetik layihə istifadə et.\n\n## 3. Addım-addım icra\n1. Öz backend repo-nu davam etdir.\n2. Search, status filter, page və page size parametrləri əlavə et.\n3. Maksimum page size təyin et və invalid parametr üçün aydın validation qaytar.\n4. Nəticələri created_at və unikal ID ilə sıralayaraq səhifələr arasında sabit sıra təmin et.\n5. Test data ilə bir neçə səhifəni oxu, filter/search birləşməsini yoxla.\n6. Empty result, invalid page size və page sərhədləri üçün test yaz.\n\n## 4. Konkret nümunə və izah\nMəsələn, `GET /projects?search=demo&status=active&page=2&pageSize=10`. `pageSize` üçün 1–50 aralığını seçib sənədləşdir. Eyni vaxtda yaranmış qeydləri ID-yə görə ikinci dəfə sırala.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, yenilənmiş endpoint, 100+ sintetik qeyd və testlər. Eyni dataset dəyişmədikdə səhifələr arasında təkrar və itmiş qeyd olmamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nDəyişməyən 100 qeyddə bütün səhifələri birləşdirəndə heç nə təkrarlanmır və itmir. Səhv parametr rədd olunur; axtarış və status filtri birlikdə işləyir.\n\n[[EN]]\n## 1. Goal\nAdd search, status filtering, and stable pagination to a project endpoint.\n\n## 2. Before you start\nYour own backend repository, SQL queries, API query parameters, and testing. Use at least 100 synthetic projects.\n\n## 3. Step-by-step work\n1. Continue your own backend repository.\n2. Add search, status filter, page, and page-size parameters.\n3. Set a maximum page size and return clear validation for invalid parameters.\n4. Sort by creation time and a unique ID to keep ordering stable across pages.\n5. Read multiple pages from test data and verify combined filter/search behavior.\n6. Test empty results, invalid page size, and page boundaries.\n\n## 4. Concrete example and explanation\nExample: `GET /projects?search=demo&status=active&page=2&pageSize=10`. Document a pageSize range such as 1–50. Use ID as a secondary sort key for equal timestamps.\n\n## 5. What to submit\nYour own GitHub repository link, updated endpoint, 100+ synthetic records, and tests. With an unchanged dataset, records must not be duplicated or skipped across pages.\n\n## 6. How to check your work\nCombine all pages of 100 unchanged records without duplicates or omissions. Reject invalid parameters and test search plus status together.","new_description":"[[AZ]]\nBöyük layihə siyahısını sabit pagination və yoxlanıla bilən filter-lərlə təqdim et.\n\nPulsuz alətlər: Python (free), FastAPI (open source), pytest (open source). Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nServe a large project list with stable pagination and validated filters.\n\nFree tools: Python (free), FastAPI (open source), pytest (open source). Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** 50 sintetik layihəni `?limit=10&offset=0&status=active` ilə ver; sabit sıra saxla.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Python layihəsində lokal HTTP endpoint və Pydantic input modeli yarat; ödənişli server lazım deyil.\n- **pytest (open source)** — https://docs.pytest.org. Lokal Python unit/integration testləri yaz, nəticələri `pytest` ilə təsdiqlə.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / backend-engineering / task-5` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. Filter parametrlərini Pydantic-lə yoxla, limit üçün 1–100 sərhəd qoy. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. SQL-də sabit `ORDER BY created_at,id` və LIMIT/OFFSET tətbiq et. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. Boş səhifə, yanlış status və növbəti səhifədə duplicate üçün test yaz. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: 50 sintetik layihəni `?limit=10&offset=0&status=active` ilə ver; sabit sıra saxla. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\n50 sintetik layihəni `?limit=10&offset=0&status=active` ilə ver; sabit sıra saxla.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nLayihə endpoint-inə axtarış, status filter-i və sabit səhifələmə əlavə edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz backend repo-n, SQL query-lər, API query parametrləri və testlər. Ən azı 100 sintetik layihə istifadə et.\n\n## 3. Addım-addım icra\n1. Öz backend repo-nu davam etdir.\n2. Search, status filter, page və page size parametrləri əlavə et.\n3. Maksimum page size təyin et və invalid parametr üçün aydın validation qaytar.\n4. Nəticələri created_at və unikal ID ilə sıralayaraq səhifələr arasında sabit sıra təmin et.\n5. Test data ilə bir neçə səhifəni oxu, filter/search birləşməsini yoxla.\n6. Empty result, invalid page size və page sərhədləri üçün test yaz.\n\n## 4. Konkret nümunə və izah\nMəsələn, `GET /projects?search=demo&status=active&page=2&pageSize=10`. `pageSize` üçün 1–50 aralığını seçib sənədləşdir. Eyni vaxtda yaranmış qeydləri ID-yə görə ikinci dəfə sırala.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, yenilənmiş endpoint, 100+ sintetik qeyd və testlər. Eyni dataset dəyişmədikdə səhifələr arasında təkrar və itmiş qeyd olmamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nDəyişməyən 100 qeyddə bütün səhifələri birləşdirəndə heç nə təkrarlanmır və itmir. Səhv parametr rədd olunur; axtarış və status filtri birlikdə işləyir.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Paginate fifty fictional projects using limit, offset and status filters.\n\n## Free tools and platforms — getting started\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Create local Python HTTP endpoints with Pydantic validation; paid hosting is unnecessary.\n- **pytest (open source)** — https://docs.pytest.org. Write local Python tests and run them with pytest.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / backend-engineering / task-5` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Validate filters and enforce a reasonable limit such as 1–100. Demonstrate it with source code, a test, file or diagram.\n4. Use stable ORDER BY columns with LIMIT/OFFSET. Demonstrate it with source code, a test, file or diagram.\n5. Test empty pages, invalid filters and duplicate-free page transitions. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Paginate fifty fictional projects using limit, offset and status filters. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nPaginate fifty fictional projects using limit, offset and status filters.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nAdd search, status filtering, and stable pagination to a project endpoint.\n\n## 2. Before you start\nYour own backend repository, SQL queries, API query parameters, and testing. Use at least 100 synthetic projects.\n\n## 3. Step-by-step work\n1. Continue your own backend repository.\n2. Add search, status filter, page, and page-size parameters.\n3. Set a maximum page size and return clear validation for invalid parameters.\n4. Sort by creation time and a unique ID to keep ordering stable across pages.\n5. Read multiple pages from test data and verify combined filter/search behavior.\n6. Test empty results, invalid page size, and page boundaries.\n\n## 4. Concrete example and explanation\nExample: `GET /projects?search=demo&status=active&page=2&pageSize=10`. Document a pageSize range such as 1–50. Use ID as a secondary sort key for equal timestamps.\n\n## 5. What to submit\nYour own GitHub repository link, updated endpoint, 100+ synthetic records, and tests. With an unchanged dataset, records must not be duplicated or skipped across pages.\n\n## 6. How to check your work\nCombine all pages of 100 unchanged records without duplicates or omissions. Reject invalid parameters and test search plus status together."},{"slug":"backend-engineering","task_number":6,"title":"Database Transactions","old_description":"[[AZ]]\nBir neçə database yazısını vahid tranzaksiyada icra et və qismən uğursuzluğu önlə.\n\n[[EN]]\nRun related database writes in one transaction and prevent partial success.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nLayihə və onun ilkin üzvlərini bir əməliyyat kimi yaratmağı təmin edəcəksən. Addımlardan biri uğursuz olsa, natamam məlumat qalmamalıdır.\n\n## 2. Başlamazdan əvvəl\nÖz backend repo-n, database transaction, foreign key və rollback anlayışları. Test bazasında işləyib sintetik məlumatlardan istifadə et.\n\n## 3. Addım-addım icra\n1. Öz backend layihəni davam etdir.\n2. Project və project_members cədvəllərini müəyyən et.\n3. Layihə və üzvlərin əlavə olunmasını bir transaction daxilində icra et.\n4. Duplicate member, olmayan user və constraint xətası yaradan test input-lar hazırla.\n5. Hər uğursuz ssenaridən sonra bazada natamam project/member qalmadığını yoxla.\n6. Uğurlu və rollback ssenarilərini avtomatlaşdırılmış testlərlə təsdiqlə.\n\n## 4. Konkret nümunə və izah\nTransaction bir neçə SQL addımının birlikdə uğurlu və ya birlikdə ləğv olunmasıdır. Layihəni əlavə etdikdən sonra olmayan istifadəçini üzv kimi əlavə etməyə çalış: əməliyyat uğursuz olduqda həmin yeni layihə də bazada qalmamalıdır.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, transaction implementasiyası, testlər və rollback sübutu. Hər hansı addım uğursuz olduqda bütün əməliyyat geri qaytarılmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nBir uğurlu və ən azı iki uğursuz sınaq var. Hər xəta sonrası layihə/üzv sayları əvvəlki vəziyyətlə müqayisə edilib; yarımçıq qeyd qalmır.\n\n[[EN]]\n## 1. Goal\nCreate a project and its initial members as one atomic operation. If a step fails, no partial data should remain.\n\n## 2. Before you start\nYour own backend repository, database transactions, foreign keys, and rollback. Work against a test database with synthetic data.\n\n## 3. Step-by-step work\n1. Continue your own backend project.\n2. Define the projects and project_members tables.\n3. Insert the project and members within one transaction.\n4. Prepare test inputs for duplicate members, nonexistent users, and constraint failures.\n5. After each failure, verify that no partial project/member rows remain.\n6. Automate success and rollback checks.\n\n## 4. Concrete example and explanation\nA transaction commits all SQL steps together or rolls them all back. Insert a project, then try to add a nonexistent member: the failed transaction must also remove that new project.\n\n## 5. What to submit\nYour own GitHub repository link, transaction implementation, tests, and rollback evidence. Any failed step must roll back the entire operation.\n\n## 6. How to check your work\nInclude one successful and at least two failing cases. Compare project/member counts before and after failure; no partial record remains.","new_description":"[[AZ]]\nBir neçə database yazısını vahid tranzaksiyada icra et və qismən uğursuzluğu önlə.\n\nPulsuz alətlər: PostgreSQL (local, free), Python (free), pytest (open source). Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nRun related database writes in one transaction and prevent partial success.\n\nFree tools: PostgreSQL (local, free), Python (free), pytest (open source). Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** Layihə yaradılarkən iki əlaqəli sətirdən ikinci INSERT səhv olsa birincisi də rollback olsun.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **PostgreSQL (local, free)** — https://www.postgresql.org. Lokal test DB-də cədvəllər qur; production Supabase/Talora bazasında SQL çalışdırma.\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **pytest (open source)** — https://docs.pytest.org. Lokal Python unit/integration testləri yaz, nəticələri `pytest` ilə təsdiqlə.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / backend-engineering / task-6` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. Bir layihə və ilkin üzvlük INSERT-lərini transaction-a yerləşdir. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. FK pozuntusu ilə qəsdən rollback sınağı qur, commit halını ayrıca yoxla. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. Rollback-dan sonra DB-də yarımçıq sətrin olmadığını testlə sübut et. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: Layihə yaradılarkən iki əlaqəli sətirdən ikinci INSERT səhv olsa birincisi də rollback olsun. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\nLayihə yaradılarkən iki əlaqəli sətirdən ikinci INSERT səhv olsa birincisi də rollback olsun.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nLayihə və onun ilkin üzvlərini bir əməliyyat kimi yaratmağı təmin edəcəksən. Addımlardan biri uğursuz olsa, natamam məlumat qalmamalıdır.\n\n## 2. Başlamazdan əvvəl\nÖz backend repo-n, database transaction, foreign key və rollback anlayışları. Test bazasında işləyib sintetik məlumatlardan istifadə et.\n\n## 3. Addım-addım icra\n1. Öz backend layihəni davam etdir.\n2. Project və project_members cədvəllərini müəyyən et.\n3. Layihə və üzvlərin əlavə olunmasını bir transaction daxilində icra et.\n4. Duplicate member, olmayan user və constraint xətası yaradan test input-lar hazırla.\n5. Hər uğursuz ssenaridən sonra bazada natamam project/member qalmadığını yoxla.\n6. Uğurlu və rollback ssenarilərini avtomatlaşdırılmış testlərlə təsdiqlə.\n\n## 4. Konkret nümunə və izah\nTransaction bir neçə SQL addımının birlikdə uğurlu və ya birlikdə ləğv olunmasıdır. Layihəni əlavə etdikdən sonra olmayan istifadəçini üzv kimi əlavə etməyə çalış: əməliyyat uğursuz olduqda həmin yeni layihə də bazada qalmamalıdır.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, transaction implementasiyası, testlər və rollback sübutu. Hər hansı addım uğursuz olduqda bütün əməliyyat geri qaytarılmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nBir uğurlu və ən azı iki uğursuz sınaq var. Hər xəta sonrası layihə/üzv sayları əvvəlki vəziyyətlə müqayisə edilib; yarımçıq qeyd qalmır.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Ensure that a failed second INSERT rolls back the whole local transaction.\n\n## Free tools and platforms — getting started\n- **PostgreSQL (local, free)** — https://www.postgresql.org. Use a local test database; never run these exercises against production Talora/Supabase.\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **pytest (open source)** — https://docs.pytest.org. Write local Python tests and run them with pytest.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / backend-engineering / task-6` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Wrap project and membership inserts in one transaction. Demonstrate it with source code, a test, file or diagram.\n4. Trigger a fictional FK error and verify rollback before testing commit. Demonstrate it with source code, a test, file or diagram.\n5. Assert no partial records remain after the failed transaction. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Ensure that a failed second INSERT rolls back the whole local transaction. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nEnsure that a failed second INSERT rolls back the whole local transaction.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nCreate a project and its initial members as one atomic operation. If a step fails, no partial data should remain.\n\n## 2. Before you start\nYour own backend repository, database transactions, foreign keys, and rollback. Work against a test database with synthetic data.\n\n## 3. Step-by-step work\n1. Continue your own backend project.\n2. Define the projects and project_members tables.\n3. Insert the project and members within one transaction.\n4. Prepare test inputs for duplicate members, nonexistent users, and constraint failures.\n5. After each failure, verify that no partial project/member rows remain.\n6. Automate success and rollback checks.\n\n## 4. Concrete example and explanation\nA transaction commits all SQL steps together or rolls them all back. Insert a project, then try to add a nonexistent member: the failed transaction must also remove that new project.\n\n## 5. What to submit\nYour own GitHub repository link, transaction implementation, tests, and rollback evidence. Any failed step must roll back the entire operation.\n\n## 6. How to check your work\nInclude one successful and at least two failing cases. Compare project/member counts before and after failure; no partial record remains."},{"slug":"backend-engineering","task_number":7,"title":"API Documentation","old_description":"[[AZ]]\nAPI davranışını OpenAPI-də sənədləşdir və nümunələrdən schema-nın işlədiyini yoxla.\n\n[[EN]]\nDocument API behavior in OpenAPI and verify the schema with examples.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nBackend API-nin istifadə qaydalarını OpenAPI sənədində dəqiq və yoxlanıla bilən göstərəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz backend repo-n, HTTP metodları, JSON schema və status code-lar. Mövcud endpoint-lərdən istifadə et.\n\n## 3. Addım-addım icra\n1. Öz backend repo-nu davam etdir.\n2. Create/list/detail/update endpoint-lərini sənədləşdir.\n3. Hər endpoint üçün method, path, parametrlər, request/response nümunəsi və status code yaz.\n4. Auth tələb olunan əməliyyatları, validation error və not-found cavablarını göstər.\n5. OpenAPI faylını validator və ya Swagger UI ilə yoxla.\n6. README-yə sənədi necə açmağı və API-ni necə sınaqdan keçirməyi əlavə et.\n\n## 4. Konkret nümunə və izah\nOpenAPI sənədini oxuyan biri endpoint-i tapıb sorğunu göndərə bilməlidir. Məsələn, `POST /tasks` üçün başlıq sahəsi, auth tələbi, uğurlu 201 və səhv 422 cavablarının JSON-larını göstər.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, OpenAPI faylı, ən azı 5 request/response nümunəsi və validation nəticəsi. Sənəd faktiki API davranışı ilə uyğun olmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nSənəddəki 5 nümunə lokal serverdə sınanıb. URL, status və JSON sahələri həqiqi cavabla uyğundur; sənəddə real token yoxdur.\n\n[[EN]]\n## 1. Goal\nDocument your backend API in OpenAPI so its behavior is clear and testable.\n\n## 2. Before you start\nYour own backend repository, HTTP methods, JSON schemas, and status codes. Document the endpoints that actually exist.\n\n## 3. Step-by-step work\n1. Continue your own backend repository.\n2. Document create/list/detail/update endpoints.\n3. For each endpoint, specify method, path, parameters, request/response examples, and status codes.\n4. Document protected operations, validation errors, and not-found responses.\n5. Validate the OpenAPI file with a validator or Swagger UI.\n6. Add instructions for viewing the docs and testing the API to the README.\n\n## 4. Concrete example and explanation\nAn OpenAPI reader should be able to find an endpoint and send a request. For `POST /tasks`, document the title field, auth requirement, 201 success, and 422 error JSON.\n\n## 5. What to submit\nYour own GitHub repository link, OpenAPI file, at least five request/response examples, and validation results. The documentation must match actual API behavior.\n\n## 6. How to check your work\nTry five documented examples against the local server. Paths, statuses, and fields match actual responses; never include real tokens.","new_description":"[[AZ]]\nAPI davranışını OpenAPI-də sənədləşdir və nümunələrdən schema-nın işlədiyini yoxla.\n\nPulsuz alətlər: FastAPI (open source), Visual Studio Code, GitHub Free. Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nDocument API behavior in OpenAPI and verify the schema with examples.\n\nFree tools: FastAPI (open source), Visual Studio Code, GitHub Free. Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** FastAPI `/docs`-da `GET /tasks`, `POST /tasks` və 422 nümunələri görünsün.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Python layihəsində lokal HTTP endpoint və Pydantic input modeli yarat; ödənişli server lazım deyil.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / backend-engineering / task-7` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. Pydantic request/response model və endpoint təsvirləri əlavə et. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. OpenAPI JSON-u export et və 2 nümunə request-i sənəddən yoxla. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. README-də auth tələbi, xətalar və işlətmə komandasını yaz. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: FastAPI `/docs`-da `GET /tasks`, `POST /tasks` və 422 nümunələri görünsün. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\nFastAPI `/docs`-da `GET /tasks`, `POST /tasks` və 422 nümunələri görünsün.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nBackend API-nin istifadə qaydalarını OpenAPI sənədində dəqiq və yoxlanıla bilən göstərəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz backend repo-n, HTTP metodları, JSON schema və status code-lar. Mövcud endpoint-lərdən istifadə et.\n\n## 3. Addım-addım icra\n1. Öz backend repo-nu davam etdir.\n2. Create/list/detail/update endpoint-lərini sənədləşdir.\n3. Hər endpoint üçün method, path, parametrlər, request/response nümunəsi və status code yaz.\n4. Auth tələb olunan əməliyyatları, validation error və not-found cavablarını göstər.\n5. OpenAPI faylını validator və ya Swagger UI ilə yoxla.\n6. README-yə sənədi necə açmağı və API-ni necə sınaqdan keçirməyi əlavə et.\n\n## 4. Konkret nümunə və izah\nOpenAPI sənədini oxuyan biri endpoint-i tapıb sorğunu göndərə bilməlidir. Məsələn, `POST /tasks` üçün başlıq sahəsi, auth tələbi, uğurlu 201 və səhv 422 cavablarının JSON-larını göstər.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, OpenAPI faylı, ən azı 5 request/response nümunəsi və validation nəticəsi. Sənəd faktiki API davranışı ilə uyğun olmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nSənəddəki 5 nümunə lokal serverdə sınanıb. URL, status və JSON sahələri həqiqi cavabla uyğundur; sənəddə real token yoxdur.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Ensure FastAPI /docs contains task endpoints and a 422 validation example.\n\n## Free tools and platforms — getting started\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Create local Python HTTP endpoints with Pydantic validation; paid hosting is unnecessary.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / backend-engineering / task-7` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Add Pydantic models and clear endpoint descriptions. Demonstrate it with source code, a test, file or diagram.\n4. Export OpenAPI JSON and verify two documented requests. Demonstrate it with source code, a test, file or diagram.\n5. Explain authentication, errors and startup commands in README. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Ensure FastAPI /docs contains task endpoints and a 422 validation example. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nEnsure FastAPI /docs contains task endpoints and a 422 validation example.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nDocument your backend API in OpenAPI so its behavior is clear and testable.\n\n## 2. Before you start\nYour own backend repository, HTTP methods, JSON schemas, and status codes. Document the endpoints that actually exist.\n\n## 3. Step-by-step work\n1. Continue your own backend repository.\n2. Document create/list/detail/update endpoints.\n3. For each endpoint, specify method, path, parameters, request/response examples, and status codes.\n4. Document protected operations, validation errors, and not-found responses.\n5. Validate the OpenAPI file with a validator or Swagger UI.\n6. Add instructions for viewing the docs and testing the API to the README.\n\n## 4. Concrete example and explanation\nAn OpenAPI reader should be able to find an endpoint and send a request. For `POST /tasks`, document the title field, auth requirement, 201 success, and 422 error JSON.\n\n## 5. What to submit\nYour own GitHub repository link, OpenAPI file, at least five request/response examples, and validation results. The documentation must match actual API behavior.\n\n## 6. How to check your work\nTry five documented examples against the local server. Paths, statuses, and fields match actual responses; never include real tokens."},{"slug":"backend-engineering","task_number":8,"title":"Backend Testing","old_description":"[[AZ]]\nService qatında unit və integration testləri ilə əsas backend davranışını qoruma altına al.\n\n[[EN]]\nProtect core backend behavior with service-level unit and integration tests.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nTask service üçün vacib iş qaydalarını avtomatlaşdırılmış testlərlə yoxlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz backend layihən, istifadə etdiyin test framework və test bazası/in-memory adapter. Testlər production məlumatına toxunmamalıdır.\n\n## 3. Addım-addım icra\n1. Öz repo-nu davam etdir.\n2. Unit testlər üçün service qaydalarını, integration test üçün isə database davranışını seç.\n3. Task yaratma, ownership, status dəyişikliyi və olmayan ID ssenarilərini əhatə et.\n4. Hər test üçün ilkin data və gözlənilən nəticəni müəyyən et.\n5. Testlər arasında data təmizlə və testləri təkrarən işə salaraq sabitliyini yoxla.\n6. Uğursuz test mesajlarının problemi anlamağa kömək etdiyini yoxla.\n\n## 4. Konkret nümunə və izah\nUnit test bir service qaydasını ayrıca yoxlayır; integration test həqiqi test bazası ilə əlaqəni də yoxlayır. Məsələn, statusu bitmiş tapşırığı yenidən açmaq qaydası service testində, foreign key davranışı bazalı testdə yoxlanılsın.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, unit və ən azı bir database integration test, testləri işə salma təlimatı və nəticə. Testlər bir-birindən asılı olmadan işləməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nTask yaratma, sahibliyə icazə, status dəyişmə və olmayan ID əhatə olunub. Testlər iki dəfə ardıcıl keçir və sıraları dəyişəndə bir-birindən asılı qalmır.\n\n[[EN]]\n## 1. Goal\nUse automated tests to verify important business rules in the task service.\n\n## 2. Before you start\nYour own backend project, its test framework, and a test database or in-memory adapter. Tests must not touch production data.\n\n## 3. Step-by-step work\n1. Continue your own repository.\n2. Separate service-rule unit tests from database integration tests.\n3. Cover task creation, ownership, status changes, and nonexistent IDs.\n4. Define setup data and expected results for every test.\n5. Clean up between tests and rerun them to check stability.\n6. Make sure failure messages help identify the problem.\n\n## 4. Concrete example and explanation\nA unit test isolates one service rule; an integration test includes the real test database. Test a completed-task status rule in isolation and foreign-key behavior with the database.\n\n## 5. What to submit\nYour own GitHub repository link, unit tests and at least one database integration test, test instructions, and results. Tests must run independently.\n\n## 6. How to check your work\nCover task creation, ownership, status changes, and missing IDs. Tests pass twice consecutively and remain independent of execution order.","new_description":"[[AZ]]\nService qatında unit və integration testləri ilə əsas backend davranışını qoruma altına al.\n\nPulsuz alətlər: Python (free), pytest (open source), Visual Studio Code. Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nProtect core backend behavior with service-level unit and integration tests.\n\nFree tools: Python (free), pytest (open source), Visual Studio Code. Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** Task create üçün 201, validation üçün 422, başqa owner üçün 403/404 testini yaz.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **pytest (open source)** — https://docs.pytest.org. Lokal Python unit/integration testləri yaz, nəticələri `pytest` ilə təsdiqlə.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / backend-engineering / task-8` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. Unit test və lokal integration test-i ayır; sabit sintetik fixture yaz. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. Ən azı 6 əsas və 3 neqativ test yarat. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. Testləri terminaldan təkrar işlə, uğursuz testi düzəldib nəticəni saxla. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: Task create üçün 201, validation üçün 422, başqa owner üçün 403/404 testini yaz. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\nTask create üçün 201, validation üçün 422, başqa owner üçün 403/404 testini yaz.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nTask service üçün vacib iş qaydalarını avtomatlaşdırılmış testlərlə yoxlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz backend layihən, istifadə etdiyin test framework və test bazası/in-memory adapter. Testlər production məlumatına toxunmamalıdır.\n\n## 3. Addım-addım icra\n1. Öz repo-nu davam etdir.\n2. Unit testlər üçün service qaydalarını, integration test üçün isə database davranışını seç.\n3. Task yaratma, ownership, status dəyişikliyi və olmayan ID ssenarilərini əhatə et.\n4. Hər test üçün ilkin data və gözlənilən nəticəni müəyyən et.\n5. Testlər arasında data təmizlə və testləri təkrarən işə salaraq sabitliyini yoxla.\n6. Uğursuz test mesajlarının problemi anlamağa kömək etdiyini yoxla.\n\n## 4. Konkret nümunə və izah\nUnit test bir service qaydasını ayrıca yoxlayır; integration test həqiqi test bazası ilə əlaqəni də yoxlayır. Məsələn, statusu bitmiş tapşırığı yenidən açmaq qaydası service testində, foreign key davranışı bazalı testdə yoxlanılsın.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, unit və ən azı bir database integration test, testləri işə salma təlimatı və nəticə. Testlər bir-birindən asılı olmadan işləməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nTask yaratma, sahibliyə icazə, status dəyişmə və olmayan ID əhatə olunub. Testlər iki dəfə ardıcıl keçir və sıraları dəyişəndə bir-birindən asılı qalmır.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Test task creation, invalid payload and cross-owner denial.\n\n## Free tools and platforms — getting started\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **pytest (open source)** — https://docs.pytest.org. Write local Python tests and run them with pytest.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / backend-engineering / task-8` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Separate unit and local integration tests with deterministic fixtures. Demonstrate it with source code, a test, file or diagram.\n4. Write six expected-behavior tests and three negative tests. Demonstrate it with source code, a test, file or diagram.\n5. Re-run the suite after fixes and record passing results. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Test task creation, invalid payload and cross-owner denial. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nTest task creation, invalid payload and cross-owner denial.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nUse automated tests to verify important business rules in the task service.\n\n## 2. Before you start\nYour own backend project, its test framework, and a test database or in-memory adapter. Tests must not touch production data.\n\n## 3. Step-by-step work\n1. Continue your own repository.\n2. Separate service-rule unit tests from database integration tests.\n3. Cover task creation, ownership, status changes, and nonexistent IDs.\n4. Define setup data and expected results for every test.\n5. Clean up between tests and rerun them to check stability.\n6. Make sure failure messages help identify the problem.\n\n## 4. Concrete example and explanation\nA unit test isolates one service rule; an integration test includes the real test database. Test a completed-task status rule in isolation and foreign-key behavior with the database.\n\n## 5. What to submit\nYour own GitHub repository link, unit tests and at least one database integration test, test instructions, and results. Tests must run independently.\n\n## 6. How to check your work\nCover task creation, ownership, status changes, and missing IDs. Tests pass twice consecutively and remain independent of execution order."},{"slug":"backend-engineering","task_number":9,"title":"Logging and Errors","old_description":"[[AZ]]\nLog və vahid xəta cavabları əlavə et ki, production problemi izlənə bilsin.\n\n[[EN]]\nAdd structured logs and consistent error responses so production failures can be traced.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nAPI sorğularını izləmək üçün request ID və strukturlaşdırılmış log əlavə edəcək, istifadəçiyə vahid error formatı qaytaracaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz backend repo-n, HTTP middleware, logging və exception handling əsasları. Log-lara email, token, parol və request body yazma.\n\n## 3. Addım-addım icra\n1. Öz backend layihəni davam etdir.\n2. Hər request-ə request ID əlavə et və cavabda da qaytar.\n3. Success, validation error və gözlənilməz server xətası ssenarilərini qur.\n4. İstifadəçiyə təhlükəsiz, ardıcıl error schema qaytar; daxili stack trace-i ictimai cavaba çıxarma.\n5. Log-ların secret və şəxsi məlumat saxlamadığını test et.\n6. Request ID və error formatını README-də sənədləşdir.\n\n## 4. Konkret nümunə və izah\nRequest ID bir sorğunu cavab və log arasında əlaqələndirir. Cavabda `{\"error\":{\"code\":\"INVALID_INPUT\",\"message\":\"Başlıq tələb olunur\",\"requestId\":\"demo-1\"}}` kimi sabit forma seç. Serverin daxili xəta izini istifadəçiyə qaytarma.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, middleware/logging implementasiyası, error response nümunələri və testlər. Log-lar sorğunu izləməyə imkan verməli, lakin secret və şəxsi məlumat açıqlamamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nUğur, validation və server xətasının hər birində request ID izlənir. Loglarda parol, token, e-poçt və tam sorğu body-si olmadığı yoxlanılıb.\n\n[[EN]]\n## 1. Goal\nAdd request IDs and structured logs to trace API requests while returning a consistent error format.\n\n## 2. Before you start\nYour own backend repository, HTTP middleware, logging, and exception handling. Never log email, tokens, passwords, or request bodies.\n\n## 3. Step-by-step work\n1. Continue your own backend project.\n2. Assign a request ID to each request and include it in the response.\n3. Create success, validation-error, and unexpected-server-error scenarios.\n4. Return a safe, consistent error schema; do not expose internal stack traces publicly.\n5. Test that logs contain no secrets or personal data.\n6. Document request IDs and the error format in the README.\n\n## 4. Concrete example and explanation\nA request ID links a response to its logs. Choose a consistent shape such as `{\"error\":{\"code\":\"INVALID_INPUT\",\"message\":\"Title is required\",\"requestId\":\"demo-1\"}}`. Do not expose internal stack traces.\n\n## 5. What to submit\nYour own GitHub repository link, middleware/logging implementation, error-response examples, and tests. Logs must help trace requests without exposing secrets or personal information.\n\n## 6. How to check your work\nTrace a request ID through success, validation failure, and server failure. Check logs for passwords, tokens, email addresses, and full request bodies.","new_description":"[[AZ]]\nLog və vahid xəta cavabları əlavə et ki, production problemi izlənə bilsin.\n\nPulsuz alətlər: Python (free), FastAPI (open source), pytest (open source). Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nAdd structured logs and consistent error responses so production failures can be traced.\n\nFree tools: Python (free), FastAPI (open source), pytest (open source). Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** Məsələn, `request_id=demo-abc`, `status=422`, `duration_ms=8` logla, parol və tokeni loglama.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Python layihəsində lokal HTTP endpoint və Pydantic input modeli yarat; ödənişli server lazım deyil.\n- **pytest (open source)** — https://docs.pytest.org. Lokal Python unit/integration testləri yaz, nəticələri `pytest` ilə təsdiqlə.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / backend-engineering / task-9` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. Mərkəzi exception handler ilə sabit JSON error schema yarat. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. Sorğulara request ID əlavə et və status/duration-u təhlükəsiz logla. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. 404, 422, 500 üçün eyni response formatını test et; stack trace-i istifadəçiyə göstərmə. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: Məsələn, `request_id=demo-abc`, `status=422`, `duration_ms=8` logla, parol və tokeni loglama. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\nMəsələn, `request_id=demo-abc`, `status=422`, `duration_ms=8` logla, parol və tokeni loglama.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nAPI sorğularını izləmək üçün request ID və strukturlaşdırılmış log əlavə edəcək, istifadəçiyə vahid error formatı qaytaracaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz backend repo-n, HTTP middleware, logging və exception handling əsasları. Log-lara email, token, parol və request body yazma.\n\n## 3. Addım-addım icra\n1. Öz backend layihəni davam etdir.\n2. Hər request-ə request ID əlavə et və cavabda da qaytar.\n3. Success, validation error və gözlənilməz server xətası ssenarilərini qur.\n4. İstifadəçiyə təhlükəsiz, ardıcıl error schema qaytar; daxili stack trace-i ictimai cavaba çıxarma.\n5. Log-ların secret və şəxsi məlumat saxlamadığını test et.\n6. Request ID və error formatını README-də sənədləşdir.\n\n## 4. Konkret nümunə və izah\nRequest ID bir sorğunu cavab və log arasında əlaqələndirir. Cavabda `{\"error\":{\"code\":\"INVALID_INPUT\",\"message\":\"Başlıq tələb olunur\",\"requestId\":\"demo-1\"}}` kimi sabit forma seç. Serverin daxili xəta izini istifadəçiyə qaytarma.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, middleware/logging implementasiyası, error response nümunələri və testlər. Log-lar sorğunu izləməyə imkan verməli, lakin secret və şəxsi məlumat açıqlamamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nUğur, validation və server xətasının hər birində request ID izlənir. Loglarda parol, token, e-poçt və tam sorğu body-si olmadığı yoxlanılıb.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Log request IDs, status and duration without logging passwords or tokens.\n\n## Free tools and platforms — getting started\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Create local Python HTTP endpoints with Pydantic validation; paid hosting is unnecessary.\n- **pytest (open source)** — https://docs.pytest.org. Write local Python tests and run them with pytest.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / backend-engineering / task-9` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Implement centralized handlers returning a consistent JSON error schema. Demonstrate it with source code, a test, file or diagram.\n4. Generate request IDs and log safe status/duration fields. Demonstrate it with source code, a test, file or diagram.\n5. Test 404, 422 and 500 without returning stack traces to clients. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Log request IDs, status and duration without logging passwords or tokens. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nLog request IDs, status and duration without logging passwords or tokens.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nAdd request IDs and structured logs to trace API requests while returning a consistent error format.\n\n## 2. Before you start\nYour own backend repository, HTTP middleware, logging, and exception handling. Never log email, tokens, passwords, or request bodies.\n\n## 3. Step-by-step work\n1. Continue your own backend project.\n2. Assign a request ID to each request and include it in the response.\n3. Create success, validation-error, and unexpected-server-error scenarios.\n4. Return a safe, consistent error schema; do not expose internal stack traces publicly.\n5. Test that logs contain no secrets or personal data.\n6. Document request IDs and the error format in the README.\n\n## 4. Concrete example and explanation\nA request ID links a response to its logs. Choose a consistent shape such as `{\"error\":{\"code\":\"INVALID_INPUT\",\"message\":\"Title is required\",\"requestId\":\"demo-1\"}}`. Do not expose internal stack traces.\n\n## 5. What to submit\nYour own GitHub repository link, middleware/logging implementation, error-response examples, and tests. Logs must help trace requests without exposing secrets or personal information.\n\n## 6. How to check your work\nTrace a request ID through success, validation failure, and server failure. Check logs for passwords, tokens, email addresses, and full request bodies."},{"slug":"backend-engineering","task_number":10,"title":"Backend Deployment","old_description":"[[AZ]]\nBackend servisini CI, health check və konfiqurasiya yoxlamaları ilə deploy-a hazırla.\n\n[[EN]]\nPrepare a backend service for deployment with CI, health checks, and configuration validation.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nBackend servisini yeni mühitdə işə düşən və CI-da yoxlanan deployment paketinə çevirəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz backend repo-n, environment variables, health endpoint, testlər və deployment əsasları. Docker və ya hosted platforma məcburi deyil; lokal işləyən alternativ qəbul edilir.\n\n## 3. Addım-addım icra\n1. Öz backend layihəni davam etdir.\n2. Start command və tələb olunan environment dəyişənlərini müəyyən et.\n3. Health endpoint əlavə et; database readiness yoxlaması varsa, onun davranışını sənədləşdir.\n4. Mövcud layihəyə uyğun Dockerfile və ya platforma start təlimatı hazırla. Docker yoxdursa, lokal alternativi təqdim et.\n5. CI workflow-da testləri və build/check addımını işə sal.\n6. Migration addımını, uğursuz start davranışını və secret-lərin necə veriləcəyini sənədləşdir. Heç bir secret-i repo-ya yazma.\n\n## 4. Konkret nümunə və izah\nHealth endpoint xidmətin işlədiyini yoxlayan, gizli məlumat göstərməyən sadə URL-dir, məsələn `/health`. CI isə hər dəyişiklikdə test/build əmrlərini avtomatik işlədən yoxlamadır. Hosting almaq məcburi deyil: lokal start + CI ilə də nəticəni göstərə bilərsən.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, deployment/start konfiqurasiyası, CI workflow, health check nəticəsi və README. Yeni mühitdə quraşdırma addımları təkrarlana bilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nTəmiz quraşdırmadan server başlayır və health sorğusu uğurludur. CI yoxlaması görünür; tələb olunan konfiqurasiya çatışmayanda başadüşülən xəta alınır.\n\n[[EN]]\n## 1. Goal\nPackage your backend so it can start in a fresh environment and be checked in CI.\n\n## 2. Before you start\nYour own backend repository, environment variables, health endpoints, tests, and deployment basics. Docker or a hosted platform is optional; a working local alternative is acceptable.\n\n## 3. Step-by-step work\n1. Continue your own backend project.\n2. Define the start command and required environment variables.\n3. Add a health endpoint and document any database-readiness behavior.\n4. Provide a Dockerfile or platform start instructions appropriate to your project. If Docker is unavailable, provide a local alternative.\n5. Configure CI to run tests and a build/check step.\n6. Document migrations, failed-start behavior, and secret configuration. Never commit secrets.\n\n## 4. Concrete example and explanation\nA health endpoint, such as `/health`, reports service health without exposing secrets. CI automatically runs test/build commands on changes. Paid hosting is optional; a local start plus CI is acceptable.\n\n## 5. What to submit\nYour own GitHub repository link, deployment/start configuration, CI workflow, health-check result, and README. Setup must be repeatable in a fresh environment.\n\n## 6. How to check your work\nStart from a clean install and verify health. Show CI results and a clear error when required configuration is missing.","new_description":"[[AZ]]\nBackend servisini CI, health check və konfiqurasiya yoxlamaları ilə deploy-a hazırla.\n\nPulsuz alətlər: GitHub Free, Python (free), FastAPI (open source), pytest (open source). Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nPrepare a backend service for deployment with CI, health checks, and configuration validation.\n\nFree tools: GitHub Free, Python (free), FastAPI (open source), pytest (open source). Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** Lokal `uvicorn app.main:app --reload` ilə açılan servisdə `/health` route-u 200 qaytarsın.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Python layihəsində lokal HTTP endpoint və Pydantic input modeli yarat; ödənişli server lazım deyil.\n- **pytest (open source)** — https://docs.pytest.org. Lokal Python unit/integration testləri yaz, nəticələri `pytest` ilə təsdiqlə.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / backend-engineering / task-10` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. README-də dependency, env.example və lokal start komandasını yaz. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. Pulsuz lokal test pipeline quraşdır; GitHub Actions Free limitinə bağlı deyilsən. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. Sıfırdan repo clone → test → start → health check sınağını qeyd et. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: Lokal `uvicorn app.main:app --reload` ilə açılan servisdə `/health` route-u 200 qaytarsın. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\nLokal `uvicorn app.main:app --reload` ilə açılan servisdə `/health` route-u 200 qaytarsın.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nBackend servisini yeni mühitdə işə düşən və CI-da yoxlanan deployment paketinə çevirəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz backend repo-n, environment variables, health endpoint, testlər və deployment əsasları. Docker və ya hosted platforma məcburi deyil; lokal işləyən alternativ qəbul edilir.\n\n## 3. Addım-addım icra\n1. Öz backend layihəni davam etdir.\n2. Start command və tələb olunan environment dəyişənlərini müəyyən et.\n3. Health endpoint əlavə et; database readiness yoxlaması varsa, onun davranışını sənədləşdir.\n4. Mövcud layihəyə uyğun Dockerfile və ya platforma start təlimatı hazırla. Docker yoxdursa, lokal alternativi təqdim et.\n5. CI workflow-da testləri və build/check addımını işə sal.\n6. Migration addımını, uğursuz start davranışını və secret-lərin necə veriləcəyini sənədləşdir. Heç bir secret-i repo-ya yazma.\n\n## 4. Konkret nümunə və izah\nHealth endpoint xidmətin işlədiyini yoxlayan, gizli məlumat göstərməyən sadə URL-dir, məsələn `/health`. CI isə hər dəyişiklikdə test/build əmrlərini avtomatik işlədən yoxlamadır. Hosting almaq məcburi deyil: lokal start + CI ilə də nəticəni göstərə bilərsən.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, deployment/start konfiqurasiyası, CI workflow, health check nəticəsi və README. Yeni mühitdə quraşdırma addımları təkrarlana bilməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nTəmiz quraşdırmadan server başlayır və health sorğusu uğurludur. CI yoxlaması görünür; tələb olunan konfiqurasiya çatışmayanda başadüşülən xəta alınır.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Run the service locally and verify GET /health returns 200.\n\n## Free tools and platforms — getting started\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Create local Python HTTP endpoints with Pydantic validation; paid hosting is unnecessary.\n- **pytest (open source)** — https://docs.pytest.org. Write local Python tests and run them with pytest.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / backend-engineering / task-10` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Document dependencies, env.example and a local start command. Demonstrate it with source code, a test, file or diagram.\n4. Run a local test pipeline without requiring paid CI or hosting. Demonstrate it with source code, a test, file or diagram.\n5. Rehearse clone → test → start → health check from a clean setup. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Run the service locally and verify GET /health returns 200. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nRun the service locally and verify GET /health returns 200.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nPackage your backend so it can start in a fresh environment and be checked in CI.\n\n## 2. Before you start\nYour own backend repository, environment variables, health endpoints, tests, and deployment basics. Docker or a hosted platform is optional; a working local alternative is acceptable.\n\n## 3. Step-by-step work\n1. Continue your own backend project.\n2. Define the start command and required environment variables.\n3. Add a health endpoint and document any database-readiness behavior.\n4. Provide a Dockerfile or platform start instructions appropriate to your project. If Docker is unavailable, provide a local alternative.\n5. Configure CI to run tests and a build/check step.\n6. Document migrations, failed-start behavior, and secret configuration. Never commit secrets.\n\n## 4. Concrete example and explanation\nA health endpoint, such as `/health`, reports service health without exposing secrets. CI automatically runs test/build commands on changes. Paid hosting is optional; a local start plus CI is acceptable.\n\n## 5. What to submit\nYour own GitHub repository link, deployment/start configuration, CI workflow, health-check result, and README. Setup must be repeatable in a fresh environment.\n\n## 6. How to check your work\nStart from a clean install and verify health. Show CI results and a clear error when required configuration is missing."}]$legacy_payload$::jsonb);
DO $preflight$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE i.slug='backend-engineering' AND t.title=e.item->>'title' AND t.instructions=e.item->>'old_instructions'
 AND t.description=e.item->>'old_description' AND t.status='published' AND t.is_required;
 IF (SELECT jsonb_array_length(payload) FROM legacy_guides)<>10 OR n<>10 THEN RAISE EXCEPTION 'Version mismatch for backend-engineering: %',n; END IF;
END; $preflight$;
DO $apply$
DECLARE n integer;
BEGIN
 UPDATE public.internship_tasks t SET instructions=e.item->>'new_instructions',description=e.item->>'new_description'
 FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 WHERE i.slug='backend-engineering' AND t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 AND t.title=e.item->>'title' AND t.instructions=e.item->>'old_instructions' AND t.description=e.item->>'old_description';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>10 THEN RAISE EXCEPTION 'Only % tasks changed for backend-engineering',n; END IF;
END; $apply$;
DO $verify$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE i.slug='backend-engineering' AND t.instructions=e.item->>'new_instructions' AND t.description=e.item->>'new_description'
 AND t.status='published' AND t.is_required;
 IF n<>10 THEN RAISE EXCEPTION 'Post-update verification failed backend-engineering: %',n; END IF;
END; $verify$;
COMMIT;
